item.command:
/bin/zsh -lc "rm -rf /tmp/tb-run && mkdir -p /tmp/tb-run && cp src/board.ts /tmp/tb-run/board.ts && cd /tmp/tb-run && tsc board.ts --target ES2020 --module esnext --strict && printf '{\"type\":\"module\"}' > package.json && cat > test.mjs <<'JS'
import { addTask, moveTask, deleteTask, countByColumn, serialize, deserialize, canMove, tasksInColumn } from './board.js';

let b = [];
b = addTask(b, '  write spec  ');
b = addTask(b, 'ship it');
b = addTask(b, '   ');              // ignored
console.log('titles', b.map(t => t.title));
console.log('counts', countByColumn(b));
console.log('todo ids', tasksInColumn(b, 'todo').length);

const id = b[0].id;
console.log('back at todo disabled?', canMove(b, id, -1) === false);
b = moveTask(b, id, -1);            // no-op
console.log('still todo', b[0].column);
b = moveTask(b, id, 1);
b = moveTask(b, id, 1);
console.log('now', b[0].column, 'forward disabled?', canMove(b, id, 1) === false);
b = moveTask(b, id, 1);             // no-op
console.log('stays done', b[0].column);

b = deleteTask(b, b[1].id);
console.log('after delete counts', countByColumn(b));

const round = deserialize(serialize(b));
console.log('roundtrip', JSON.stringify(round) === JSON.stringify(b));
console.log('bad input', deserialize('not json'), deserialize(null), deserialize('[{\"id\":1}]'));
JS
node test.mjs"

